// Basic error handling using nonnegative integers (u32).
// This enum is the error type E in Result<T, E>.
#[derive(Debug, PartialEq)]
pub enum ArithmeticError {
    // SubtractionUnderflow, 
    DivisionByZero,
}

// Another way to print errors is to implement the Display trait for the error type.
// Display is implemented manually; Debug above is generated by derive.
// Using the variant name here makes both formats produce the same text.
impl std::fmt::Display for ArithmeticError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::DivisionByZero => write!(f, "DivisionByZero (by Display)"),
        }
    }
}

// Private: callers outside this module cannot call `subtract` directly.
fn subtract(a: u32, b: u32) -> Result<u32, ArithmeticError> {    
    //if a < b {
        //// A negative result cannot be represented by u32.
        //  return Err(ArithmeticError::SubtractionUnderflow);
    // }
    Ok(a - b)
}

// Public: compute the integer quotient by repeatedly subtracting b from a.
// For example, 10 / 3 returns Ok(3); the remainder is discarded.
pub fn divide(a: u32, b: u32) -> Result<u32, ArithmeticError> {
    if b == 0 {
        // Subtracting zero would never make progress in the loop.
        return Err(ArithmeticError::DivisionByZero);
    }

    let mut remainder: u32 = a;
    let mut quotient: u32 = 0;

    loop {
        if remainder < b {
            break;
        }

        // `?` extracts the Ok value, or returns Err from this function early.
        // The check above ensures this subtraction will not underflow.
        remainder = subtract(remainder, b)?;
        quotient += 1;
    }

    Ok(quotient)
}

// Tests inside this module can access its private subtraction function.
// Run `cargo test` to check both successful and failing operations.
#[cfg(test)]
mod tests {
    use super::{divide, subtract, ArithmeticError};

    #[test]
    fn subtraction_success_and_underflow() {
        assert_eq!(subtract(10, 3), Ok(7));
        assert_eq!(subtract(3, 3), Ok(0));
        // assert_eq!(subtract(3, 10), Err(ArithmeticError::SubtractionUnderflow));
    }

    #[test]
    fn integer_division_and_zero_quotient() {
        assert_eq!(divide(12, 3), Ok(4));
        assert_eq!(divide(10, 3), Ok(3));
        assert_eq!(divide(2, 3), Ok(0));
        assert_eq!(divide(0, 3), Ok(0));
    }

    #[test]
    fn division_by_zero_is_an_error() {
        assert_eq!(divide(10, 0), Err(ArithmeticError::DivisionByZero));
        assert_eq!(divide(0, 0), Err(ArithmeticError::DivisionByZero));
    }
}
